    53→func runResume(branchName string, force bool) error {
    54→	// Check if we're already on this branch
    55→	currentBranch, err := GetCurrentBranch()
    56→	if err == nil && currentBranch == branchName {
    57→		// Already on the branch, skip checkout
    58→		return resumeFromCurrentBranch(branchName, force)
    59→	}
    60→
    61→	// Check if branch exists locally
    62→	exists, err := BranchExistsLocally(branchName)
    63→	if err != nil {
    64→		return fmt.Errorf("failed to check branch: %w", err)
    65→	}
    66→
    67→	if !exists {
    68→		// Branch doesn't exist locally, check if it exists on remote
    69→		remoteExists, err := BranchExistsOnRemote(branchName)
    70→		if err != nil {
    71→			return fmt.Errorf("failed to check remote branch: %w", err)
    72→		}
    73→
    74→		if !remoteExists {
    75→			return fmt.Errorf("branch '%s' not found locally or on origin", branchName)
    76→		}
    77→
    78→		// Ask user if they want to fetch from remote
    79→		shouldFetch, err := promptFetchFromRemote(branchName)
    80→		if err != nil {
    81→			return err
    82→		}
    83→		if !shouldFetch {
    84→			return nil
    85→		}
    86→
    87→		// Fetch and checkout the remote branch
    88→		fmt.Fprintf(os.Stderr, "Fetching branch '%s' from origin...\n", branchName)
    89→		if err := FetchAndCheckoutRemoteBranch(branchName); err != nil {
    90→			return err
    91→		}
    92→		fmt.Fprintf(os.Stderr, "Switched to branch '%s'\n", branchName)
    93→	} else {
    94→		// Branch exists locally, check for uncommitted changes before checkout
    95→		hasChanges, err := HasUncommittedChanges()
    96→		if err != nil {
    97→			return fmt.Errorf("failed to check for uncommitted changes: %w", err)
    98→		}
    99→		if hasChanges {
   100→			return errors.New("you have uncommitted changes. Please commit or stash them first")
   101→		}
   102→
   103→		// Checkout the branch
   104→		if err := CheckoutBranch(branchName); err != nil {
   105→			return err
   106→		}
   107→		fmt.Fprintf(os.Stderr, "Switched to branch '%s'\n", branchName)
   108→	}
   109→
   110→	return resumeFromCurrentBranch(branchName, force)
   111→}
