   113→func resumeFromCurrentBranch(branchName string, force bool) error {
   114→	repo, err := openRepository()
   115→	if err != nil {
   116→		return fmt.Errorf("not a git repository: %w", err)
   117→	}
   118→
   119→	// Find a commit with an Entire-Checkpoint trailer, looking at branch-only commits
   120→	result, err := findBranchCheckpoint(repo, branchName)
   121→	if err != nil {
   122→		return err
   123→	}
   124→	if result.checkpointID == "" {
   125→		fmt.Fprintf(os.Stderr, "No Entire checkpoint found on branch '%s'\n", branchName)
   126→		return nil
   127→	}
   128→
   129→	// If there are newer commits without checkpoints, ask for confirmation.
   130→	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
   131→	if result.newerCommitsExist && !force {
   132→		fmt.Fprintf(os.Stderr, "Found checkpoint in an older commit.\n")
   133→		fmt.Fprintf(os.Stderr, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
   134→		fmt.Fprintf(os.Stderr, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))
   135→
   136→		shouldResume, err := promptResumeFromOlderCheckpoint()
   137→		if err != nil {
   138→			return err
   139→		}
   140→		if !shouldResume {
   141→			fmt.Fprintf(os.Stderr, "Resume cancelled.\n")
   142→			return nil
   143→		}
   144→	}
   145→
   146→	checkpointID := result.checkpointID
   147→
   148→	// Get metadata branch tree for lookups
   149→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
   150→	if err != nil {
   151→		// No local metadata branch, check if remote has it
   152→		return checkRemoteMetadata(repo, checkpointID)
   153→	}
   154→
   155→	// Look up metadata from sharded path
   156→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, paths.CheckpointPath(checkpointID))
   157→	if err != nil {
   158→		// Checkpoint exists in commit but no local metadata - check remote
   159→		return checkRemoteMetadata(repo, checkpointID)
   160→	}
   161→
   162→	return resumeSession(metadata.SessionID, checkpointID, force)
   163→}
