   165→// branchCheckpointResult contains the result of searching for a checkpoint on a branch.
   166→type branchCheckpointResult struct {
   167→	checkpointID      string
   168→	commitHash        string
   169→	commitMessage     string
   170→	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
   171→	newerCommitCount  int  // count of branch-only commits without checkpoints
   172→}
   173→
   174→// findBranchCheckpoint finds the most recent commit with an Entire-Checkpoint trailer
   175→// among commits that are unique to this branch (not reachable from the default branch).
   176→// This handles the case where main has been merged into the feature branch.
   177→func findBranchCheckpoint(repo *git.Repository, branchName string) (*branchCheckpointResult, error) {
   178→	result := &branchCheckpointResult{}
   179→
   180→	// Get HEAD commit
   181→	head, err := repo.Head()
   182→	if err != nil {
   183→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
   184→	}
   185→
   186→	headCommit, err := repo.CommitObject(head.Hash())
   187→	if err != nil {
   188→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
   189→	}
   190→
   191→	// First, check if HEAD itself has a checkpoint (most common case)
   192→	if checkpointID, found := paths.ParseCheckpointTrailer(headCommit.Message); found {
   193→		result.checkpointID = checkpointID
   194→		result.commitHash = head.Hash().String()
   195→		result.commitMessage = headCommit.Message
   196→		result.newerCommitsExist = false
   197→		return result, nil
   198→	}
   199→
   200→	// HEAD doesn't have a checkpoint - find branch-only commits
   201→	// Get the default branch name
   202→	defaultBranch := getDefaultBranchFromRemote(repo)
   203→	if defaultBranch == "" {
   204→		// Fallback: try common names
   205→		for _, name := range []string{"main", "master"} {
   206→			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
   207→				defaultBranch = name
   208→				break
   209→			}
   210→		}
   211→	}
   212→
   213→	// If we can't find a default branch, or we're on it, just walk all commits
   214→	if defaultBranch == "" || defaultBranch == branchName {
   215→		return findCheckpointInHistory(headCommit, nil), nil
   216→	}
   217→
   218→	// Get the default branch reference
   219→	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
   220→	if err != nil {
   221→		// Default branch doesn't exist locally, fall back to walking all commits
   222→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
   223→	}
   224→
   225→	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
   226→	if err != nil {
   227→		// Can't get default commit, fall back to walking all commits
   228→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
   229→	}
   230→
   231→	// Find merge base
   232→	mergeBase, err := headCommit.MergeBase(defaultCommit)
   233→	if err != nil || len(mergeBase) == 0 {
   234→		// No common ancestor, fall back to walking all commits
   235→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
   236→	}
   237→
   238→	// Walk from HEAD to merge base, looking for checkpoint
   239→	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
   240→}
