   242→// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
   243→// If stopAt is provided, stops when reaching that commit (exclusive).
   244→// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
   245→// It distinguishes between merge commits (bringing in other branches) and regular commits
   246→// (actual branch work) to avoid false warnings after merging main.
   247→func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointResult {
   248→	result := &branchCheckpointResult{}
   249→	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
   250→	const maxCommits = 100 // Limit search depth
   251→	totalChecked := 0
   252→
   253→	current := start
   254→	for current != nil && totalChecked < maxCommits {
   255→		// Stop if we've reached the boundary
   256→		if stopAt != nil && current.Hash == *stopAt {
   257→			break
   258→		}
   259→
   260→		// Check for checkpoint trailer
   261→		if checkpointID, found := paths.ParseCheckpointTrailer(current.Message); found {
   262→			result.checkpointID = checkpointID
   263→			result.commitHash = current.Hash.String()
   264→			result.commitMessage = current.Message
   265→			// Only warn about branch work commits, not merge commits
   266→			result.newerCommitsExist = branchWorkCommits > 0
   267→			result.newerCommitCount = branchWorkCommits
   268→			return result
   269→		}
   270→
   271→		// Only count regular commits (not merge commits) as "branch work"
   272→		if current.NumParents() <= 1 {
   273→			branchWorkCommits++
   274→		}
   275→
   276→		totalChecked++
   277→
   278→		// Move to parent (first parent for merge commits - follows the main line)
   279→		if current.NumParents() == 0 {
   280→			break
   281→		}
   282→		parent, err := current.Parent(0)
   283→		if err != nil {
   284→			// Can't get parent, treat as end of history
   285→			break
   286→		}
   287→		current = parent
   288→	}
   289→
   290→	// No checkpoint found
   291→	return result
   292→}
