   316→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/sessions
   317→// and provides guidance to the user.
   318→func checkRemoteMetadata(repo *git.Repository, checkpointID string) error {
   319→	// Try to get remote metadata branch tree
   320→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
   321→	if err != nil {
   322→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
   323→		fmt.Fprintf(os.Stderr, "The entire/sessions branch may not exist locally or on the remote.\n")
   324→		return nil //nolint:nilerr // Informational message, not a fatal error
   325→	}
   326→
   327→	// Check if the checkpoint exists on the remote
   328→	_, err = strategy.ReadCheckpointMetadata(remoteTree, paths.CheckpointPath(checkpointID))
   329→	if err != nil {
   330→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
   331→		return nil //nolint:nilerr // Informational message, not a fatal error
   332→	}
   333→
   334→	// Metadata exists on remote but not locally
   335→	fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available locally\n", checkpointID)
   336→	fmt.Fprintf(os.Stderr, "The metadata exists on origin. To fetch it, run:\n")
   337→	fmt.Fprintf(os.Stderr, "  git fetch origin entire/sessions:entire/sessions\n")
   338→	fmt.Fprintf(os.Stderr, "\nThen run this command again.\n")
   339→	return nil
   340→}
