   342→// resumeSession restores and displays the resume command for a specific session.
   343→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
   344→// If force is false, prompts for confirmation when local logs have newer timestamps.
   345→func resumeSession(sessionID, checkpointID string, force bool) error {
   346→	// Get the current agent (auto-detect or use default)
   347→	ag, err := agent.Detect()
   348→	if err != nil {
   349→		ag = agent.Default()
   350→		if ag == nil {
   351→			return fmt.Errorf("no agent available: %w", err)
   352→		}
   353→	}
   354→
   355→	// Get repo root for session directory lookup
   356→	// Use repo root instead of CWD because Claude stores sessions per-repo,
   357→	// and running from a subdirectory would look up the wrong session directory
   358→	repoRoot, err := paths.RepoRoot()
   359→	if err != nil {
   360→		return fmt.Errorf("failed to get repository root: %w", err)
   361→	}
   362→
   363→	sessionDir, err := ag.GetSessionDir(repoRoot)
   364→	if err != nil {
   365→		return fmt.Errorf("failed to determine session directory: %w", err)
   366→	}
   367→
   368→	// Create directory if it doesn't exist
   369→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
   370→		return fmt.Errorf("failed to create session directory: %w", err)
   371→	}
   372→
   373→	// Get strategy and restore sessions using full checkpoint data
   374→	strat := GetStrategy()
   375→
   376→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
   377→	if restorer, ok := strat.(strategy.LogsOnlyRestorer); ok {
   378→		// Create a logs-only rewind point to trigger full multi-session restore
   379→		point := strategy.RewindPoint{
   380→			IsLogsOnly:   true,
   381→			CheckpointID: checkpointID,
   382→		}
   383→
   384→		if err := restorer.RestoreLogsOnly(point, force); err != nil {
   385→			// Fall back to single-session restore
   386→			return resumeSingleSession(ag, sessionID, checkpointID, sessionDir, repoRoot, force)
   387→		}
   388→
   389→		// Get checkpoint metadata to show all sessions
   390→		repo, err := openRepository()
   391→		if err != nil {
   392→			// Just show the primary session - graceful fallback
   393→			agentSID := ag.ExtractAgentSessionID(sessionID)
   394→			fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
   395→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
   396→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(agentSID))
   397→			return nil //nolint:nilerr // Graceful fallback to single session
   398→		}
   399→
   400→		metadataTree, err := strategy.GetMetadataBranchTree(repo)
   401→		if err != nil {
   402→			agentSID := ag.ExtractAgentSessionID(sessionID)
   403→			fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
   404→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
   405→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(agentSID))
   406→			return nil //nolint:nilerr // Graceful fallback to single session
   407→		}
   408→
   409→		metadata, err := strategy.ReadCheckpointMetadata(metadataTree, paths.CheckpointPath(checkpointID))
   410→		if err != nil || metadata.SessionCount <= 1 {
   411→			// Single session or can't read metadata - show standard single session output
   412→			agentSID := ag.ExtractAgentSessionID(sessionID)
   413→			fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
   414→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
   415→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(agentSID))
   416→			return nil //nolint:nilerr // Graceful fallback to single session
   417→		}
   418→
   419→		// Multi-session: show all resume commands with prompts
   420→		checkpointPath := paths.CheckpointPath(checkpointID)
   421→		sessionPrompts := strategy.ReadAllSessionPromptsFromTree(metadataTree, checkpointPath, metadata.SessionCount, metadata.SessionIDs)
   422→
   423→		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", metadata.SessionCount)
   424→		for i, sid := range metadata.SessionIDs {
   425→			agentSID := ag.ExtractAgentSessionID(sid)
   426→			cmd := ag.FormatResumeCommand(agentSID)
   427→
   428→			var prompt string
   429→			if i < len(sessionPrompts) {
   430→				prompt = sessionPrompts[i]
   431→			}
   432→
   433→			if i == len(metadata.SessionIDs)-1 {
   434→				if prompt != "" {
   435→					fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, prompt)
   436→				} else {
   437→					fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
   438→				}
   439→			} else {
   440→				if prompt != "" {
   441→					fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, prompt)
   442→				} else {
   443→					fmt.Fprintf(os.Stderr, "  %s\n", cmd)
   444→				}
   445→			}
   446→		}
   447→
   448→		return nil
   449→	}
   450→
   451→	// Strategy doesn't support LogsOnlyRestorer, fall back to single session
   452→	return resumeSingleSession(ag, sessionID, checkpointID, sessionDir, repoRoot, force)
   453→}
