   455→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
   456→// Always overwrites existing session logs to ensure consistency with checkpoint state.
   457→// If force is false, prompts for confirmation when local log has newer timestamps.
   458→func resumeSingleSession(ag agent.Agent, sessionID, checkpointID, sessionDir, repoRoot string, force bool) error {
   459→	agentSessionID := ag.ExtractAgentSessionID(sessionID)
   460→	sessionLogPath := filepath.Join(sessionDir, agentSessionID+".jsonl")
   461→
   462→	strat := GetStrategy()
   463→
   464→	logContent, _, err := strat.GetSessionLog(checkpointID)
   465→	if err != nil {
   466→		if errors.Is(err, strategy.ErrNoMetadata) {
   467→			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
   468→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
   469→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(agentSessionID))
   470→			return nil
   471→		}
   472→		return fmt.Errorf("failed to get session log: %w", err)
   473→	}
   474→
   475→	// Check if local file has newer timestamps than checkpoint
   476→	if !force {
   477→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
   478→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
   479→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
   480→
   481→		if status == strategy.StatusLocalNewer {
   482→			sessions := []strategy.SessionRestoreInfo{{
   483→				SessionID:      sessionID,
   484→				Status:         status,
   485→				LocalTime:      localTime,
   486→				CheckpointTime: checkpointTime,
   487→			}}
   488→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
   489→			if promptErr != nil {
   490→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
   491→			}
   492→			if !shouldOverwrite {
   493→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
   494→				return nil
   495→			}
   496→		}
   497→	}
   498→
   499→	// Create an AgentSession with the native data
   500→	agentSession := &agent.AgentSession{
   501→		SessionID:  agentSessionID,
   502→		AgentName:  ag.Name(),
   503→		RepoPath:   repoRoot,
   504→		SessionRef: sessionLogPath,
   505→		NativeData: logContent,
   506→	}
   507→
   508→	// Write the session using the agent's WriteSession method
   509→	if err := ag.WriteSession(agentSession); err != nil {
   510→		return fmt.Errorf("failed to write session: %w", err)
   511→	}
   512→
   513→	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
   514→	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
   515→	fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
   516→	fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(agentSessionID))
   517→
   518→	return nil
   519→}
